  function installHeaderNotifications(){
    const host=document.querySelector('.top-right');if(!host||document.getElementById('di-admin-notification-wrap'))return;
    const wrap=document.createElement('div');wrap.id='di-admin-notification-wrap';wrap.className='di-admin-notification-wrap';
    wrap.innerHTML='<button type="button" class="icon-btn di-admin-notification-trigger" id="di-admin-notification-trigger" aria-label="Notifications" title="Notifications" aria-haspopup="dialog" aria-expanded="false" aria-controls="di-admin-notification-popover"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9Z"/><path d="M10 21h4"/></svg></button><section class="di-admin-notification-popover" id="di-admin-notification-popover" role="dialog" aria-labelledby="di-admin-notification-title" hidden><header><div><h2 id="di-admin-notification-title">Notifications</h2><span class="di-admin-notification-summary"></span></div><button type="button" class="di-admin-notification-close" aria-label="Close notifications">×</button></header><div class="di-admin-notification-list"></div><button type="button" class="di-admin-notification-all" data-open-action-center>Open Action Center <span aria-hidden="true">→</span></button></section>';
    const role=host.querySelector('.role-pill');if(role)host.insertBefore(wrap,role);else host.appendChild(wrap);
    wrap.addEventListener('click',event=>{
      const trigger=event.target.closest('#di-admin-notification-trigger');
      if(trigger){notificationsOpen=!notificationsOpen;const popover=wrap.querySelector('#di-admin-notification-popover');popover.hidden=!notificationsOpen;trigger.setAttribute('aria-expanded',String(notificationsOpen));renderHeaderNotifications();return;}
      if(event.target.closest('.di-admin-notification-close')){notificationsOpen=false;wrap.querySelector('#di-admin-notification-popover').hidden=true;wrap.querySelector('#di-admin-notification-trigger').setAttribute('aria-expanded','false');return;}
      const item=event.target.closest('[data-header-notification-index]');
      if(item){const chosen=actionItems()[Number(item.dataset.headerNotificationIndex)];notificationsOpen=false;wrap.querySelector('#di-admin-notification-popover').hidden=true;wrap.querySelector('#di-admin-notification-trigger').setAttribute('aria-expanded','false');chosen?.run();return;}
      if(event.target.closest('[data-open-action-center]')){notificationsOpen=false;wrap.querySelector('#di-admin-notification-popover').hidden=true;wrap.querySelector('#di-admin-notification-trigger').setAttribute('aria-expanded','false');window.renderPage('operations');openOpsTab('action');}
    });
    document.addEventListener('click',event=>{if(notificationsOpen&&!wrap.contains(event.target)){notificationsOpen=false;wrap.querySelector('#di-admin-notification-popover').hidden=true;wrap.querySelector('#di-admin-notification-trigger').setAttribute('aria-expanded','false');}});
    document.addEventListener('keydown',event=>{if(event.key==='Escape'&&notificationsOpen){notificationsOpen=false;wrap.querySelector('#di-admin-notification-popover').hidden=true;wrap.querySelector('#di-admin-notification-trigger').setAttribute('aria-expanded','false');wrap.querySelector('#di-admin-notification-trigger').focus();}});
    renderHeaderNotifications();
  }
  function openOpsTab(tab){operationsTab=tab;const host=document.getElementById('di-ops-panel');if(!host)return;document.querySelectorAll('[data-ops-tab]').forEach(button=>{const active=button.dataset.opsTab===tab;button.classList.toggle('is-active',active);button.setAttribute('aria-selected',String(active))});host.innerHTML=tab==='action'?renderOpsActions():tab==='reviews'?renderReviewQueue():tab==='exceptions'?renderExceptions():tab==='flags'?renderFlags():renderAudit();bindOpsPanel(host)}
  function renderOpsActions(){const rows=actionItems();return rows.length?'<div class="di-action-list">'+rows.map((row,index)=>'<article class="di-action-row"><span class="di-priority di-priority-'+esc(row.priority.toLowerCase().replace(/\s+/g,'-'))+'">'+esc(row.priority)+'</span><div><strong>'+esc(row.title)+'</strong><p>'+esc(row.copy)+'</p></div><button type="button" class="di-ops-cta" data-action-index="'+index+'">'+esc(row.action)+' <span aria-hidden="true">→</span></button></article>').join('')+'</div>':'<div class="di-ops-empty"><span>✓</span><strong>Nothing needs attention</strong><p>New submissions and blocked campaigns will appear here for review.</p></div>'}
  function renderReviewQueue(){const rows=pendingReviews();return '<div class="di-ops-section-head"><div><span class="di-eyebrow">SUBMISSION PATH</span><h2>Review workflow</h2><p>Pending → In Review → Changes Requested, Approved or Rejected. Rejections need a reason.</p></div><span class="di-count-pill">'+rows.length+' open</span></div>'+(rows.length?'<div class="di-review-queue">'+rows.map(row=>'<article class="di-review-queue-row"><div class="di-review-entity-icon">'+(row.type==='campaign'?'✦':'♡')+'</div><div class="di-review-queue-main"><div class="di-review-queue-meta"><span class="di-type-pill">'+(row.type==='campaign'?'Campaign':'Charity')+'</span><span class="badge '+(normalizedStatus(row.item.status)==='In Review'?'amber':'gray')+'">'+esc(normalizedStatus(row.item.status))+'</span></div><h3>'+esc(row.item.name)+'</h3><p>'+esc(applicantAndName(row.type,row.item))+' · '+esc(row.item.submitted||'Recently submitted')+'</p>'+ (row.item.reviewNote?'<div class="di-note-preview"><strong>Visible note</strong><span>'+esc(row.item.reviewNote)+'</span></div>':'')+'</div><button type="button" class="di-ops-cta" data-open-workflow="'+esc(row.type)+'|'+esc(row.item.id)+'">Review submission <span aria-hidden="true">→</span></button></article>').join('')+'</div>':'<div class="di-ops-empty"><span>✓</span><strong>Review queue is clear</strong><p>New submissions will appear here with their complete status history.</p></div>')}
  function actualExceptions(){
    const rows=read(KEY.exceptions,[]),stored=Array.isArray(rows)?rows:[],selectedValue=read(KEY.recipients,[]),selected=Array.isArray(selectedValue)?selectedValue:[];
    selected.forEach(key=>{
      const [type,...parts]=String(key).split(':'),id=parts.join(':');if(!id||!['charity','campaign'].includes(type))return;
      const entity=type==='charity'?D.charities.find(item=>item.name===id):D.campaigns.find(item=>item.slug===id);
      const eligible=type==='charity'?!!entity&&entity.status==='Verified':!!entity&&entity.status==='Active';
      if(!eligible&&!stored.some(row=>row.recipientKey===key&&!row.resolved))stored.unshift({id:'EXC-'+Date.now().toString(36).toUpperCase()+'-'+stored.length,recipientKey:key,recipient:entity&&entity.name||id,recipientType:type,user:'Current demo member',userId:'Current browser account',reason:entity?'Recipient is no longer eligible for allocation':'Selected recipient is no longer listed',status:'Needs user choice',createdAt:isoNow(),resolved:false});
    });
    stored.sort((a,b)=>Number(!!a.resolved)-Number(!!b.resolved));write(KEY.exceptions,stored);return stored;
  }
  function usableFallback(pref){
    if(pref&&['notify','hold'].includes(pref.mode))return true;
    return !!(pref&&pref.mode==='backup'&&pref.backup&&D.charities.some(charity=>charity.name===pref.backup&&charity.status==='Verified'));
  }
  function renderExceptions(){
    const rows=actualExceptions(),pref=read(KEY.fallback,{}),canApply=usableFallback(pref),buttonLabel=canApply?'Apply saved preference':'Notify user to choose';
    return '<div class="di-ops-section-head"><div><span class="di-eyebrow">MONTH-END CHECKS</span><h2>Allocation exception queue</h2><p>When a selected recipient becomes ineligible or a campaign closes, no points are silently redirected.</p></div><span class="di-count-pill">'+rows.filter(row=>!row.resolved).length+' open</span></div><div class="di-exception-example"><span class="di-example-tag">EXAMPLE SCENARIO</span><div><strong>Campaign closed</strong><p>The user is asked to choose a replacement, or the saved fallback preference is applied.</p></div><span class="di-exception-state">User choice required</span></div>'+(rows.length?'<div class="di-exception-list">'+rows.map(row=>'<article class="di-exception-row"><div class="di-exception-symbol" aria-hidden="true"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 8v4"/><path d="M12 16h.01"/></svg></div><div class="di-exception-copy"><div><span class="di-type-pill">'+(row.recipientType==='campaign'?'Campaign':'Charity')+'</span><span class="badge '+(row.resolved?'green':'amber')+'">'+esc(row.resolved?'Resolved · '+row.resolution:row.status||'Needs user choice')+'</span></div><h3>'+esc(row.recipient)+'</h3><p>'+esc(row.reason)+' · '+esc(row.user||'Member')+'</p>'+(!row.resolved?'<small>No replacement is assigned without the user’s saved choice.</small>':'')+'</div>'+(!row.resolved?'<button type="button" class="di-ops-cta" data-exception="'+esc(row.id)+'">'+buttonLabel+' <span aria-hidden="true">→</span></button>':'')+'</article>').join('')+'</div>':'<div class="di-ops-empty"><span>✓</span><strong>No open allocation exceptions</strong><p>If an active selection becomes unavailable, it will be listed here for review.</p></div>');
  }
  function resolveException(id){
    const rows=actualExceptions(),item=rows.find(row=>row.id===id);if(!item)return;
    const pref=read(KEY.fallback,{}),preferenceValid=usableFallback(pref),mode=preferenceValid?pref.mode:'notify',backupValid=mode==='backup';
    const now=isoNow(),inboxValue=read(KEY.inbox,[]),inbox=Array.isArray(inboxValue)?inboxValue:[],selectedValue=read(KEY.recipients,[]),selected=Array.isArray(selectedValue)?selectedValue:[],auditValue=read(KEY.audit,[]),audit=Array.isArray(auditValue)?auditValue:[];
    let nextSelected=selected.slice();
    const notice=mode==='notify'
      ?{title:'Choose a replacement recipient',copy:preferenceValid?'Your selected recipient is unavailable. Please choose a replacement before the next monthly allocation.':'Your selected recipient is unavailable and no usable fallback is saved. Your share is on hold until you choose a replacement or update your fallback preference.'}
      :mode==='hold'
        ?{title:'Your recipient share is on hold',copy:'Your selected recipient is unavailable. Your share will stay on hold until you choose what to do.'}
        :{title:'Your backup charity was selected',copy:'Your selected recipient became unavailable. Your saved backup charity is now in your monthly split.'};
    inbox.unshift({id:'exception-'+id,type:'UPDATE',title:notice.title,source:item.recipient,date:humanDate(now),copy:notice.copy});
    if(mode==='notify'){item.status='User notified · choice required';item.resolved=false;item.resolution='';}
    else{
      item.resolved=true;item.status='Resolved';item.resolution=mode==='hold'?'held points':'backup charity: '+pref.backup;
      if(backupValid){nextSelected=selected.filter(key=>key!==item.recipientKey);const backupKey='charity:'+pref.backup;if(!nextSelected.includes(backupKey))nextSelected.push(backupKey);nextSelected=nextSelected.slice(-5);}
    }
    const auditReason=mode==='notify'?'No usable saved preference; user asked to choose a replacement':mode==='hold'?'Applied saved preference: hold points':'Applied saved preference: backup charity '+pref.backup;
    audit.unshift({id:'AUD-'+Date.now().toString(36),actor:'Dotis Admin',at:now,entity:item.recipient,label:'allocation exception',what:mode==='notify'?'User notified':'Resolved per saved preference',reason:auditReason});
    const entries=[{key:KEY.exceptions,value:rows},{key:KEY.audit,value:audit.slice(0,300)},{key:KEY.inbox,value:inbox}];if(backupValid)entries.push({key:KEY.recipients,value:nextSelected});
    if(!writeTransaction(entries)){toast('The exception could not be saved. Please retry.');return;}
    renderPage('operations');toast(mode==='notify'?'The user has been notified and must choose what happens next.':'Exception resolved using the saved preference.');
  }
  function renderFlags(){const rows=reviewFlags();return '<div class="di-ops-section-head"><div><span class="di-eyebrow">INVESTIGATE, THEN DECIDE</span><h2>Human-review flags</h2><p>These are prompts for an administrator. A flag never rejects a submission or suspends an account.</p></div><span class="di-count-pill">'+rows.length+' flags</span></div>'+(rows.length?'<div class="di-flag-grid">'+rows.map(row=>'<article class="di-flag-card"><span class="di-flag-kind">'+esc(row.type)+'</span><h3>'+esc(row.item.name)+'</h3><p>'+esc(row.reason)+'</p><button type="button" class="di-ops-cta" data-open-workflow="'+esc(row.type==='campaign'?'campaign':'charity')+'|'+esc(row.item.id)+'">Investigate <span aria-hidden="true">→</span></button></article>').join('')+'</div>':'<div class="di-ops-empty"><span>✓</span><strong>No review flags</strong><p>Possible duplicates, missing information and unusual account patterns will appear here for a person to check.</p></div>')}
  function renderAudit(){const rows=read(KEY.audit,[]);return '<div class="di-ops-section-head"><div><span class="di-eyebrow">WHO · WHEN · WHAT · WHY</span><h2>Audit history</h2><p>Review decisions and important edits are recorded with an administrator, timestamp and reason.</p></div><span class="di-count-pill">'+rows.length+' records</span></div>'+(rows.length?'<div class="di-audit-shell"><table class="di-audit-table"><thead><tr><th>Admin</th><th>When</th><th>What changed</th><th>Record</th><th>Reason</th></tr></thead><tbody>'+rows.map(row=>'<tr><td>'+esc(row.actor||'Dotis Admin')+'</td><td>'+esc(humanDate(row.at))+'</td><td>'+esc(row.what||'Updated')+'</td><td>'+esc(row.entity||row.label||'—')+'</td><td>'+esc(row.reason||'—')+'</td></tr>').join('')+'</tbody></table></div>':'<div class="di-ops-empty"><span>⌁</span><strong>No decisions recorded yet</strong><p>Review decisions, changes and removals will appear here with their reasons.</p></div>')}
  function bindOpsPanel(host){host.querySelectorAll('[data-action-index]').forEach(button=>button.addEventListener('click',()=>actionItems()[Number(button.dataset.actionIndex)]?.run()));host.querySelectorAll('[data-open-workflow]').forEach(button=>button.addEventListener('click',()=>{const [type,id]=button.dataset.openWorkflow.split('|');workflowModal(type,id)}));host.querySelectorAll('[data-exception]').forEach(button=>button.addEventListener('click',()=>resolveException(button.dataset.exception)));}
  function ensureReasonField(){const form=document.getElementById('edit-form'),grid=form&&form.querySelector('.form-grid');if(!form||!grid||grid.querySelector('#di-edit-reason'))return;const field=document.createElement('div');field.className='form-field full di-edit-reason-field';field.innerHTML='<label for="di-edit-reason">Reason for this change <span aria-hidden="true">*</span></label><textarea id="di-edit-reason" name="diEditReason" rows="2" required placeholder="Add a short reason to the audit record"></textarea>';grid.appendChild(field)}
